mutations.find:
const { recs, forecast } = advised(sim, person);
const first = recs.find((r) => r.forecast);
if (!first) return recs;

mutations.replace:
const { recs: all, forecast } = advised(sim, person);
const w0 = person.experience?.advised;
const tr = all.filter((r) => r.forecast);
const recs = w0 && tr.length > 1 && tr[0]!.target === w0.target && sim.now - w0.since > 28 * MS_DAY ? [tr[1]!, ...all.filter((r) => r !== tr[1])] : all;
const first = recs.find((r) => r.forecast);
if (!first) return recs;
